import {validateBank} from '../engine.js';
const $=id=>document.getElementById(id);let questions=[],results=[],activeId=null,pendingImport=null,dirty=false,revision=null;
async function api(url,method='GET',body){const response=await fetch('/api/admin/'+url,{method,headers:{'Content-Type':'application/json','X-Smartup-Request':'1'},...(body?{body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok){if(response.status===401){$('admin-workspace').hidden=true;$('login-panel').hidden=false;$('logout').hidden=true;}throw new Error(data.error);}return data;}
function status(message){$('admin-status').textContent=message;}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportBank(){download('smartup-question-bank.json',JSON.stringify({version:1,status:'draft',questions},null,2),'application/json');}
function filtered(){return questions.filter(q=>q.subject===$('subject-filter').value&&q.level===$('level-filter').value);}
function renderList(){const list=filtered();$('bank-summary').textContent=`${list.length} questions in this bucket · ${questions.length} total · Minimum 9 per bucket`;$('question-list').replaceChildren();list.forEach((q,i)=>{const button=document.createElement('button');button.type='button';button.setAttribute('aria-pressed',String(q.id===activeId));const label=document.createElement('small');label.textContent=`${i+1} · ${q.topic}`;button.append(label,document.createTextNode(q.prompt));button.addEventListener('click',()=>{if(dirty&&!confirm('Discard unsaved question edits?'))return;selectQuestion(q);});$('question-list').append(button);});}
function selectQuestion(q){activeId=q?.id||null;dirty=false;renderList();$('editor-title').textContent=q?'Edit question':'Add question';$('edit-topic').value=q?.topic||'';$('edit-prompt').value=q?.prompt||'';for(let i=0;i<4;i++)$('option-'+i).value=q?.options[i]||'';$('edit-answer').value=q?.answer??0;$('edit-explanation').value=q?.explanation||'';$('delete-question').hidden=!q;}
async function load(){const data=await api('questions');questions=data.questions;revision=data.revision;$('login-panel').hidden=true;$('admin-workspace').hidden=false;$('logout').hidden=false;selectQuestion(filtered()[0]);}
async function saveBank(next){validateBank(next);const data=await api('questions','PUT',{questions:next,revision});questions=next;revision=data.revision;dirty=false;renderList();}
$('login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;$('login-error').textContent='';try{await api('login','POST',{password:$('admin-password').value});$('admin-password').value='';await load();}catch(error){$('login-error').textContent=error.message;}finally{button.disabled=false;}});
$('logout').addEventListener('click',async()=>{try{await api('logout','POST',{});location.reload();}catch(error){status(error.message);}});
for(const id of ['subject-filter','level-filter'])$(id).addEventListener('change',()=>{if(dirty&&!confirm('Discard unsaved question edits?')){const q=questions.find(q=>q.id===activeId);if(q){$('subject-filter').value=q.subject;$('level-filter').value=q.level;}return;}selectQuestion(filtered()[0]);status('');});
$('question-editor').addEventListener('input',()=>{dirty=true;});
$('question-editor').addEventListener('submit',async event=>{event.preventDefault();const original=questions.find(q=>q.id===activeId);const q={id:activeId||`custom-${crypto.randomUUID()}`,subject:original?.subject||$('subject-filter').value,level:original?.level||$('level-filter').value,topic:$('edit-topic').value.trim(),prompt:$('edit-prompt').value.trim(),options:[0,1,2,3].map(i=>$('option-'+i).value.trim()),answer:Number($('edit-answer').value),explanation:$('edit-explanation').value.trim()};const next=original?questions.map(item=>item.id===q.id?q:item):[...questions,q];$('save-question').disabled=true;try{await saveBank(next);selectQuestion(q);status('Question saved. New journeys will use the updated bank.');}catch(error){status(error.message);}finally{$('save-question').disabled=false;}});
$('add-question').addEventListener('click',()=>{if(dirty&&!confirm('Discard unsaved question edits?'))return;selectQuestion(null);$('edit-topic').focus();});
$('delete-question').addEventListener('click',async()=>{if(!activeId||!confirm('Delete this question? A bucket must still contain at least 9 questions.'))return;try{await saveBank(questions.filter(q=>q.id!==activeId));selectQuestion(filtered()[0]);status('Question deleted.');}catch(error){status(error.message);}});
$('export-bank').addEventListener('click',exportBank);
$('import-bank').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>1500000)throw new Error('Choose a JSON file under 1.5 MB.');const data=JSON.parse(await file.text());pendingImport=Array.isArray(data)?data:data.questions;validateBank(pendingImport);$('import-summary').textContent=`This file contains ${pendingImport.length} valid questions across all four subjects.`;$('import-confirm').hidden=false;$('confirm-import').focus();}catch(error){status(error.message);}event.target.value='';});
$('cancel-import').addEventListener('click',()=>{$('import-confirm').hidden=true;pendingImport=null;});
$('confirm-import').addEventListener('click',async()=>{if(!pendingImport)return;$('confirm-import').disabled=true;try{exportBank();await saveBank(pendingImport);pendingImport=null;$('import-confirm').hidden=true;selectQuestion(filtered()[0]);status('Question bank imported. Your previous bank was downloaded.');}catch(error){status(error.message);}finally{$('confirm-import').disabled=false;}});
async function loadResults(){try{results=[];let offset=0;do{const page=await api('results?offset='+offset);results.push(...page.results);offset=page.nextOffset;}while(offset!==null);status(`${results.length} saved ${results.length===1?'journey':'journeys'}`);$('results-body').replaceChildren();$('empty-results').hidden=results.length>0;for(const row of results){const tr=document.createElement('tr');const values=[row.name,row.phone,`Class ${row.grade} · ${row.subject}`,row.result?.label||'In progress',row.result?`${row.result.correct} / ${row.result.answered}`:'—',new Date(row.created_at).toLocaleString()];for(const value of values){const td=document.createElement('td');td.textContent=value;tr.append(td);}const td=document.createElement('td'),button=document.createElement('button');button.textContent='Delete';button.setAttribute('aria-label',`Delete saved journey for ${row.name}`);button.addEventListener('click',async()=>{if(!confirm(`Permanently delete this saved journey for ${row.name}? If it is their current subject attempt, this allows them to take that subject again.`))return;try{await api('results/'+row.id,'DELETE',{});await loadResults();status('Journey deleted.');}catch(error){status(error.message);}});td.append(button);tr.append(td);$('results-body').append(tr);}}catch(error){status(error.message);}}
$('refresh-results').addEventListener('click',loadResults);
$('export-results').addEventListener('click',()=>{const escape=value=>'"'+String(value??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[['Name','Phone','Grade','Subject','Assessed level','Correct','Answered','Lives','Started','Status'],...results.map(r=>[r.name,r.phone,r.grade,r.subject,r.result?.label||'',r.result?.correct??'',r.result?.answered??'',r.result?.lives??'',r.created_at,r.status])];download('smartup-student-results.csv','\uFEFF'+rows.map(r=>r.map(escape).join(',')).join('\r\n'),'text/csv;charset=utf-8');});
const tabs=[$('questions-tab'),$('results-tab')];function tabSelect(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;$(t.getAttribute('aria-controls')).hidden=!selected;});if(tab===$('results-tab'))loadResults();}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>tabSelect(tab));tab.addEventListener('keydown',event=>{let index;if(event.key==='ArrowRight'||event.key==='ArrowLeft')index=1-i;else if(event.key==='Home')index=0;else if(event.key==='End')index=1;if(index===undefined)return;event.preventDefault();tabSelect(tabs[index]);tabs[index].focus();});});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
load().catch(()=>{});
